	if (bk_pm_lpo_src_get() == PM_LPO_SRC_DIVD)
		start_req_param->lp_clk_accuracy = 20;
	else if (bk_pm_lpo_src_get() == PM_LPO_SRC_X32K)
		start_req_param->lp_clk_accuracy = 100;
	else
		start_req_param->lp_clk_accuracy = 1000;

#else
	start_req_param->lp_clk_accuracy = 20;
#endif
