	 * frozen-FSM investigation.
	 *
	 * mm_active() is the only writer that moves the NXMAC FSM off 0
	 * (nxmac_next_state_setf(3) -> 0x49100038 = 0x30), and it runs in the
	 * MM_START_REQ handler tail alongside ke_state_set(TASK_MM, MM_ACTIVE).
	 * The scan-end probe reports mmstate=MM_IDLE(0) while rw_msg_send here
	 * returns ret=0, i.e. MM_START_CFM came back successfully.  Unlike the
	 * NXMAC registers, ke_state is the library's OWN memory variable, so
	 * this pair cannot be dismissed as a bad register read:
	 *   post mmstate==MM_ACTIVE(1) -> MM did start; something later reverts
	 *                                 it, so look between here and scan.
	 *   post mmstate==MM_IDLE(0)   -> the handler produced a success CFM
	 *                                 without ever reaching mm_active /
	 *                                 ke_state_set; the window closes to
	 *                                 mm_start_req_handler internals.
	 * States: 0=MM_IDLE 1=MM_ACTIVE 2=GOING_TO_IDLE 3=HOST_BYPASSED
	 *         4=MM_NO_IDLE (lmac_msg.h:885-899).
	 * On its own short lines: the console truncated the wider RSTWIN lines
	 * on previous boards, and these two fields are the scarce ones. */
	/* LATCHED, not just printed: on the previous board the `post` line was
	 * lost entirely and the `pre` line was sliced in half by a concurrent
	 * `[wifi] clk post-start:` from another thread, so the one measurement
	 * this image existed to take never arrived.  Console interleaving is not
	 * something a shorter line fixes, so the values are also stored for the
	 * scan-end diagnostic to re-print from a quiet context. */
	g_mmstart_mmstate_pre = (unsigned char)ke_state_get(TASK_MM);
	g_mmstart_r38_pre     = (*(volatile unsigned int *)0x49100038u);
	bk_printf("[MMSTART] pre s=%d r38=%08x\r\n",
		(int)g_mmstart_mmstate_pre, g_mmstart_r38_pre);
	ret = rw_msg_send(start_req_param, 1, MM_START_CFM, NULL);
	g_mmstart_mmstate_post = (unsigned char)ke_state_get(TASK_MM);
	g_mmstart_r38_post     = (*(volatile unsigned int *)0x49100038u);
