/****************************************************************************
 * Hardware register snapshots around the MM bring-up handshake
 *
 * These sample absolute SoC registers (NXMAC 0x49100000, its interrupt block
 * 0x49108000, the modem clock 0x49000000 and CRM 0x49850000) at the four
 * moments the MM_RESET/MM_START handshake passes through.  MMIO addresses are
 * fixed by the SoC and do not move when code is recompiled, which is what
 * makes this class of probe worth keeping -- unlike anything derived from a
 * disassembly of library RAM, which drifts.
 *
 * The reads have to happen inside the vendored senders (rw_msg_send_reset,
 * rw_msg_send_start, sa_station_cfg80211_init): the register state being
 * measured only exists for the duration of that handshake, and we never call
 * those functions directly.  So the vendored files keep a single call each --
 * the same shape as bk7258_scan_diag_record() -- and all probe logic,
 * storage and formatting lives here.  Latching rather than printing in place
 * is deliberate: printing from those contexts raced with other threads'
 * console output and destroyed the measurement (see the g_mmstart_* note
 * above).
 *
 * `aux` carries a value only the caller's translation unit can see, so the
 * vendored side stays one line: ke_state_get(TASK_MM) at the START sites, and
 * the rw_msg_send() return code at the POST sites.  Pass 0 when unused.
 ****************************************************************************/

enum bk7258_hwprobe_site_e
{
  BK7258_HWPROBE_PRE_RESET = 0,
  BK7258_HWPROBE_POST_RESET,
  BK7258_HWPROBE_PRE_START,
  BK7258_HWPROBE_POST_START,
  BK7258_HWPROBE_NSITES
};

void bk7258_hwprobe_latch(enum bk7258_hwprobe_site_e site, int aux);
void bk7258_hwprobe_report(void);

